mapper.insert:
insert into t_gkcjx(ksh, gkcjx01, gkcjx02, gkcjx10, gkcjx03, gkcjx_byzc, gkcjx_bd)
select ksh, GKCJX01, GKCJX02, GKCJX06, GKCJX07, GKCJX25, GKCJX24
from ${tableName};

-- 专业志愿上载
insert into t_zyzy(ksh, zydh, zyxh)
select ksh, zydh1 as zydh, '1' from ${tableName}
where zydh1 is not null
union all
select ksh, zydh2 as zydh, '2'  from ${tableName}
where zydh2 is not null
union all
select ksh, zydh3 as zydh, '3'  from ${tableName}
where zydh3 is not null
union all
select ksh, zydh4 as zydh, '4'  from ${tableName}
where zydh4 is not null
union all
select ksh, zydh5 as zydh, '5'  from ${tableName}
where zydh5 is not null
union all
select ksh, zydh6 as zydh, '6'  from ${tableName}
where zydh6 is not null
order by ksh

insert into t_zyzy(ksh, zydh, zyxh)
select ksh, zydh, zyxh
from ${tableName}
